sql.if:
AND EXISTS (
    SELECT 1 FROM dept_position dp_scope
    WHERE dp_scope.position_id = c.position_id
      AND dp_scope.dept_id = #{scopeDeptId}
      AND dp_scope.status = 1
)

mapper.select:
SELECT 
FROM course c
LEFT JOIN position p ON p.id = c.position_id AND p.deleted = 0

    c.deleted = 0


        AND c.course_name LIKE CONCAT('%', #{courseName}, '%')


        AND c.position_id = #{positionId}


        AND c.course_type = #{courseType}


        AND c.status = #{status}


ORDER BY c.create_time DESC

SELECT COUNT(1)
FROM dept_position
WHERE position_id = #{positionId}
  AND dept_id = #{deptId}
  AND status = 1

SELECT DISTINCT p.id AS position_id, p.position_code, p.position_name, p.sort_no, p.status AS position_status, p.create_by AS position_create_by, p.create_time AS position_create_time, p.update_by AS position_update_by, p.update_time AS position_update_time, p.deleted AS position_deleted, dp.dept_id, d.dept_name FROM position p INNER JOIN dept_position dp ON dp.position_id = p.id AND dp.status = 1 LEFT JOIN sys_dept d ON d.dept_id = dp.dept_id AND d.del_flag = '0' WHERE p.deleted = 0 AND p.status = 1
AND dp.dept_id = #{scopeDeptId}
ORDER BY p.sort_no ASC, p.id ASC
